"use client";

import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";
import {
  Store as StoreIcon,
  Tag,
  Clock,
  ShoppingCart,
  ChevronRight,
  CheckCircle2,
} from "lucide-react";
import { useAppContext } from "@/context/AppContext";
import { formatVND } from "@/lib/priceUtils";
import { DEALS_DATA } from "@/data/mockData";

const STORES = ["Tất cả", "Winmart", "Bach Hoa Xanh", "Coop Food"];

export default function DealsPage() {
  const [golden, setGolden] = useState({
    active: false,
    label: "11:00–13:00 và 17:00–19:00",
  });
  const { addToCart } = useAppContext();
  const [notice, setNotice] = useState("");
  const [query, setQuery] = useState("");
  const [activeStore, setActiveStore] = useState("Tất cả");
  const [deals, setDeals] = useState<typeof DEALS_DATA>([]),
    [demo, setDemo] = useState(true),
    [error, setError] = useState("");
  useEffect(() => {
    fetch("/api/deals")
      .then(async (r) => {
        const d = await r.json();
        if (!r.ok) throw Error(d.message);
        setDeals(d.deals);
        if (d.golden) setGolden(d.golden);
        setDemo(d.demo);
      })
      .catch((e) => setError(e.message));
  }, []);

  const filteredDeals =
    activeStore === "Tất cả"
      ? deals.filter((d) => d.name.toLowerCase().includes(query.toLowerCase()))
      : deals.filter(
          (d) =>
            d.store === activeStore &&
            d.name.toLowerCase().includes(query.toLowerCase()),
        );

  const handleAddToCart = (deal: (typeof DEALS_DATA)[0]) => {
    setNotice(`Đã thêm ${deal.name} vào giỏ hàng.`);
    addToCart({
      ingredient: {
        id: deal.ingredientId,
        name: deal.name,
        price: deal.price,
        unit: deal.unit,
        quantity: 1,
        store: deal.store,
        category: deal.category,
        image: deal.image,
      },
      recipeId: "deal",
      recipeTitle: "Ưu đãi siêu thị",
      quantity: 1,
    });
  };

  return (
    <div className="space-y-8 pb-12">
      {error && (
        <p role="alert" className="text-error">
          {error}
        </p>
      )}
      <input
        aria-label="Tìm thực phẩm giảm giá"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Tìm nguyên liệu bạn đang thiếu…"
        className="w-full border border-outline-variant rounded-xl p-3"
      />
      {notice && (
        <p role="status" className="text-primary">
          {notice}
        </p>
      )}
      {/* Hero Banner */}
      <motion.div
        initial={{ opacity: 0, y: 16 }}
        animate={{ opacity: 1, y: 0 }}
        className="relative overflow-hidden rounded-3xl bg-surface border border-outline-variant shadow-sm h-64 md:h-80"
      >
        <div className="absolute inset-0 bg-gradient-to-r from-primary-container/80 to-transparent z-10" />
        {/* You would normally use a real image here based on Figma */}
        <div className="absolute inset-0 bg-[url('https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&q=80&w=1200')] bg-cover bg-center" />

        <div className="relative z-20 h-full flex flex-col justify-center px-8 md:px-12 max-w-xl">
          <span className="px-3 py-1 bg-primary text-on-primary text-xs font-bold rounded-full w-max mb-4 inline-flex items-center gap-1.5">
            <Tag className="w-3.5 h-3.5" /> Ưu đãi tham khảo
          </span>
          <h1 className="text-3xl md:text-5xl font-extrabold text-on-surface tracking-tight mb-3">
            Giờ Vàng Mỗi Ngày
          </h1>
          <p className="text-on-surface-variant text-sm md:text-base mb-6">
            {golden.label} · Thứ Hai đến Chủ nhật, giờ Việt Nam.{" "}
            {golden.active
              ? "Đang diễn ra — chọn thực phẩm cho bữa ngon hôm nay."
              : "Ngoài giờ vàng — giá ưu đãi sẽ áp dụng trong khung giờ tiếp theo."}
          </p>
        </div>
      </motion.div>

      {/* Filter Bar */}
      <div className="flex items-center gap-2 overflow-x-auto pb-2 scrollbar-hide">
        {STORES.map((store) => (
          <button
            key={store}
            onClick={() => setActiveStore(store)}
            className={`
              whitespace-nowrap px-5 py-2.5 rounded-full text-sm font-bold transition-all
              ${
                activeStore === store
                  ? "bg-primary text-on-primary shadow-md"
                  : "bg-surface border border-outline-variant text-on-surface hover:bg-surface-container"
              }
            `}
          >
            {store}
          </button>
        ))}
      </div>

      {/* Deals Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredDeals.map((deal, idx) => (
          <motion.div
            key={deal.id}
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: idx * 0.05 }}
            className="group rounded-3xl bg-surface border border-outline-variant overflow-hidden hover:shadow-[var(--shadow-elevation-2)] transition-shadow"
          >
            {/* Image placeholder */}
            <div className="h-40 bg-surface-container relative overflow-hidden">
              {deal.image.startsWith("http") || deal.image.startsWith("/") ? (
                <img
                  src={deal.image}
                  alt={deal.name}
                  className="w-full h-full object-cover"
                />
              ) : (
                <div className="w-full h-full flex items-center justify-center text-6xl">
                  {deal.image}
                </div>
              )}
              <div className="absolute top-3 left-3 px-2.5 py-1 bg-error text-on-error text-xs font-bold rounded-lg shadow-sm">
                -{Math.round((1 - deal.price / deal.originalPrice) * 100)}%
              </div>
              <div className="absolute top-3 right-3 px-2.5 py-1 bg-surface/90 backdrop-blur-sm text-on-surface text-xs font-bold rounded-lg shadow-sm flex items-center gap-1">
                <StoreIcon className="w-3.5 h-3.5 text-primary" />
                {deal.store}
              </div>
            </div>

            <div className="p-5">
              <h3 className="text-base font-bold text-on-surface mb-2 line-clamp-1 group-hover:text-primary transition-colors">
                {deal.name}
              </h3>

              <div className="flex items-center justify-between mt-4">
                <div>
                  <p className="text-xs text-on-surface-variant line-through mb-0.5">
                    {formatVND(deal.originalPrice)}
                  </p>
                  <p className="text-lg font-black text-primary">
                    {formatVND(deal.price)}
                  </p>
                </div>

                <button
                  aria-label={`Thêm ${deal.name} vào giỏ`}
                  onClick={() => handleAddToCart(deal)}
                  className="w-10 h-10 rounded-xl bg-primary-container text-primary flex items-center justify-center hover:bg-primary hover:text-on-primary transition-colors cursor-pointer"
                >
                  <ShoppingCart className="w-5 h-5" />
                </button>
              </div>

              <div className="mt-4 pt-4 border-t border-outline-variant/50 flex items-center gap-2 text-[11px] font-medium text-error">
                <Clock className="w-3.5 h-3.5" />
                {demo
                  ? "Kiểm tra ưu đãi tại cửa hàng"
                  : `Hiệu lực: ${deal.expiresIn}`}
              </div>
            </div>
          </motion.div>
        ))}

        {filteredDeals.length === 0 && (
          <div className="col-span-full py-12 text-center">
            <Tag className="w-12 h-12 text-outline mx-auto mb-3" />
            <h3 className="text-lg font-bold text-on-surface">
              Không có ưu đãi nào
            </h3>
            <p className="text-on-surface-variant">
              Thử chọn một siêu thị khác xem sao nhé.
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import Link from "next/link";
import { motion, AnimatePresence } from "framer-motion";
import {
  CalendarDays,
  Sparkles,
  Wallet,
  ArrowLeft,
  Plus,
  CheckCircle2,
  Trash2,
  ListPlus,
  Sun,
  Sunset,
  Moon,
} from "lucide-react";
import { useAppContext, type CartItem } from "@/context/AppContext";
import { useCatalogRecipes } from "@/lib/use-catalog-recipes";
import { formatVND } from "@/lib/priceUtils";
import RecipeImage from "@/components/ui/RecipeImage";

import { useRouter } from "next/navigation";
import { Lock, Crown } from "lucide-react";

const DAYS = ["CN", "T2", "T3", "T4", "T5", "T6", "T7"];
const MEAL_TYPES = [
  { id: "breakfast", label: "Sáng", icon: Sun },
  { id: "lunch", label: "Trưa", icon: Sunset },
  { id: "dinner", label: "Tối", icon: Moon },
] as const;

export default function WeeklyMealPlanPage() {
  const recipes = useCatalogRecipes();
  const { state, setWeeklyPlanMeal, addMultipleToCart } = useAppContext();
  const [activeDay, setActiveDay] = useState("T4");
  const router = useRouter();

  const weeklyPlan = state.weeklyPlan;

  const budget = state.userBudget > 0 ? state.userBudget * 7 : 7000000;

  // Calculate today's total
  const todayMeals = weeklyPlan[activeDay] || {};
  const todayTotal = Object.values(todayMeals).reduce((sum, recipe) => {
    return sum + (recipe?.totalPrice || 0);
  }, 0);

  const handleRandomSuggest = () => {
    if (!recipes.length) return;
    MEAL_TYPES.forEach(({ id }) => {
      if (!todayMeals[id]) {
        const randomRecipe =
          recipes[
            (DAYS.indexOf(activeDay) +
              MEAL_TYPES.findIndex((m) => m.id === id)) %
              recipes.length
          ];
        setWeeklyPlanMeal(activeDay, id, randomRecipe);
      }
    });
  };

  const handleAddRandomMeal = (mealType: "breakfast" | "lunch" | "dinner") => {
    if (!recipes.length) return;
    const randomRecipe =
      recipes[
        (recipes.findIndex((r) => r.id === todayMeals[mealType]?.id) + 1) %
          recipes.length
      ];
    setWeeklyPlanMeal(activeDay, mealType, randomRecipe);
  };

  const handleUpdateCart = () => {
    const allCartItems: CartItem[] = [];

    // Gather all ingredients from the entire weekly plan
    Object.values(weeklyPlan).forEach((dayMeals) => {
      Object.values(dayMeals).forEach((recipe) => {
        if (recipe) {
          recipe.ingredients.forEach((ing) => {
            allCartItems.push({
              ingredient: ing,
              recipeId: recipe.id,
              recipeTitle: recipe.title,
              quantity: ing.quantity,
            });
          });
        }
      });
    });

    if (allCartItems.length > 0) {
      addMultipleToCart(allCartItems);
    }
    router.push("/grocery-store");
  };

  return (
    <div className="space-y-6 pb-12">
      <Link
        href="/meal-plan/ai"
        className="block bg-emerald-900 text-white rounded-2xl p-5 font-bold"
      >
        Tạo thực đơn bằng AI theo gói thành viên →
      </Link>
      {/* Header */}
      <motion.div
        initial={{ opacity: 0, y: 16 }}
        animate={{ opacity: 1, y: 0 }}
        className="space-y-4"
      >
        <Link
          href="/meal-plan"
          className="inline-flex items-center gap-1.5 text-sm text-on-surface-variant hover:text-primary transition-colors"
        >
          <ArrowLeft className="w-4 h-4" />
          Quay lại Gợi ý món ăn
        </Link>

        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 rounded-2xl gradient-primary flex items-center justify-center shadow-md">
              <CalendarDays className="w-6 h-6 text-white" />
            </div>
            <div>
              <h1 className="text-2xl font-extrabold text-on-surface tracking-tight">
                Lên lịch bữa ăn thủ công
              </h1>
              <p className="text-sm text-on-surface-variant">
                Tiết kiệm thời gian và tiền bạc với kế hoạch ăn uống thông minh.
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2 p-3 rounded-2xl bg-surface border border-outline-variant shadow-sm">
            <Wallet className="w-8 h-8 text-primary bg-primary/10 p-1.5 rounded-xl" />
            <div>
              <div className="text-xs text-on-surface-variant font-medium">
                Ngân sách tuần này:
              </div>
              <div className="text-sm font-bold text-on-surface">
                {formatVND(budget)}
              </div>
              <div className="text-[10px] text-secondary font-semibold mt-0.5">
                Chi phí dự kiến, chưa gồm giao hàng
              </div>
            </div>
          </div>
        </div>
      </motion.div>

      {/* Main Content Grid with Premium Overlay if active */}
      <div className="relative">
        <div className={`grid grid-cols-1 lg:grid-cols-[1fr_320px] gap-6 `}>
          {/* Left: Weekly Calendar & Day Plan */}
          <motion.div
            initial={{ opacity: 0, x: -16 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.1 }}
            className="bg-surface rounded-3xl border border-outline-variant shadow-sm p-6"
          >
            {/* Day Tabs */}
            <div className="flex items-center gap-2 overflow-x-auto pb-4 mb-4 border-b border-outline-variant scrollbar-hide">
              {DAYS.map((day) => (
                <button
                  key={day}
                  onClick={() => setActiveDay(day)}
                  className={`
                  flex-1 min-w-[64px] flex flex-col items-center justify-center py-3 rounded-2xl transition-all cursor-pointer
                  ${
                    activeDay === day
                      ? "bg-primary text-on-primary shadow-md"
                      : "bg-surface-container hover:bg-surface-container-high text-on-surface-variant"
                  }
                `}
                >
                  <span
                    className={`text-xs ${activeDay === day ? "opacity-90" : ""}`}
                  >
                    Thứ
                  </span>
                  <span className="text-lg font-bold mt-0.5">
                    {day === "CN" ? "CN" : day.replace("T", "")}
                  </span>
                </button>
              ))}
            </div>

            {/* Meals for selected day */}
            <div className="space-y-6">
              <div className="flex items-center justify-between mb-2">
                <h2 className="text-lg font-bold text-on-surface">
                  Thực đơn{" "}
                  {activeDay === "CN"
                    ? "Chủ nhật"
                    : `Thứ ${activeDay.replace("T", "")}`}
                </h2>
                <button
                  onClick={handleRandomSuggest}
                  className="text-xs font-semibold text-primary hover:underline flex items-center gap-1 cursor-pointer"
                >
                  <Sparkles className="w-3.5 h-3.5" />
                  Gợi ý ngẫu nhiên
                </button>
              </div>

              {MEAL_TYPES.map(({ id, label, icon: Icon }) => {
                const recipe = weeklyPlan[activeDay]?.[id];

                return (
                  <div key={id} className="flex gap-4">
                    {/* Timeline indicator */}
                    <div className="flex flex-col items-center">
                      <div className="w-10 h-10 rounded-full bg-primary-container flex items-center justify-center text-primary z-10 shadow-sm border-4 border-surface">
                        <Icon className="w-4 h-4" />
                      </div>
                      <div className="w-0.5 h-full bg-outline-variant/50 -my-2" />
                    </div>

                    {/* Meal content */}
                    <div className="flex-1 pb-6">
                      <h3 className="text-sm font-bold text-on-surface-variant mb-3">
                        {label}
                      </h3>

                      {recipe ? (
                        <div className="flex items-start gap-4 p-3 rounded-2xl border border-outline-variant hover:border-primary/50 transition-colors group bg-surface">
                          <div className="w-20 h-20 rounded-xl overflow-hidden flex-shrink-0 bg-surface-container">
                            <RecipeImage
                              recipeId={recipe.id}
                              src={recipe.image}
                              alt={recipe.title}
                              variant="card"
                            />
                          </div>
                          <div className="flex-1 min-w-0 py-1">
                            <h4 className="text-sm font-bold text-on-surface line-clamp-1">
                              {recipe.title}
                            </h4>
                            <div className="flex items-center gap-2 mt-1 mb-2 text-xs text-on-surface-variant">
                              <span className="font-semibold text-primary">
                                {formatVND(recipe.totalPrice)}
                              </span>
                              <span>•</span>
                              <span>
                                {recipe.prepTime + recipe.cookTime} phút
                              </span>
                            </div>
                            <div className="flex items-center gap-2">
                              <button
                                onClick={() =>
                                  setWeeklyPlanMeal(activeDay, id, undefined)
                                }
                                className="text-xs font-semibold text-error hover:bg-error/10 px-2 py-1 rounded-md transition-colors flex items-center gap-1 cursor-pointer"
                              >
                                <Trash2 className="w-3 h-3" /> Xóa
                              </button>
                            </div>
                          </div>
                          <button className="w-10 h-10 rounded-xl bg-primary text-on-primary flex items-center justify-center flex-shrink-0 self-center hover:bg-primary-dark transition-colors shadow-sm cursor-pointer">
                            <ListPlus className="w-5 h-5" />
                          </button>
                        </div>
                      ) : (
                        <button
                          onClick={() => handleAddRandomMeal(id)}
                          className="w-full flex flex-col items-center justify-center py-6 border-2 border-dashed border-outline-variant rounded-2xl text-on-surface-variant hover:bg-surface-container hover:border-primary/50 hover:text-primary transition-all cursor-pointer"
                        >
                          <Plus className="w-6 h-6 mb-2" />
                          <span className="text-sm font-semibold">
                            Thêm món {label.toLowerCase()}
                          </span>
                        </button>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </motion.div>

          {/* Right: Pantry & Summary */}
          <motion.div
            initial={{ opacity: 0, x: 16 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.2 }}
            className="space-y-6"
          >
            {/* Pantry */}
            <div className="bg-surface rounded-3xl border border-outline-variant shadow-sm p-6">
              <h3 className="text-sm font-bold text-on-surface mb-4">
                Nguồn dự trữ nhà bạn
              </h3>
              <div className="space-y-3">
                {state.pantryIngredients.length > 0 ? (
                  state.pantryIngredients.map((item) => (
                    <div key={item} className="flex items-center gap-3">
                      <CheckCircle2 className="w-5 h-5 text-primary" />
                      <span className="text-sm text-on-surface font-medium">
                        {item}
                      </span>
                    </div>
                  ))
                ) : (
                  <p className="text-sm text-on-surface-variant italic">
                    Không có nguyên liệu dự trữ.
                  </p>
                )}
              </div>
              <button className="w-full mt-5 py-2.5 rounded-xl border border-outline-variant text-sm font-semibold text-primary hover:bg-primary/5 transition-colors cursor-pointer">
                Thêm nguyên liệu
              </button>
            </div>

            {/* Summary Box */}
            <div className="bg-primary-container/20 rounded-3xl border border-primary/20 p-6">
              <h3 className="text-sm font-bold text-on-surface mb-2">
                Tổng kết {activeDay}
              </h3>
              <div className="text-3xl font-black text-primary mb-4">
                {formatVND(todayTotal)}{" "}
                <span className="text-sm font-semibold text-on-surface-variant">
                  / ngày
                </span>
              </div>
              <p className="text-xs text-on-surface-variant mb-6 leading-relaxed">
                Thực đơn hôm nay rất cân bằng. Có thể tận dụng{" "}
                {state.pantryIngredients[0] || "nước tương"} sẵn có ở nhà để nấu
                bữa tối!
              </p>
              <button
                onClick={handleUpdateCart}
                className="w-full py-3.5 rounded-2xl gradient-primary text-on-primary font-bold shadow-md hover:shadow-lg transition-all flex items-center justify-center gap-2 cursor-pointer"
              >
                <CheckCircle2 className="w-5 h-5" />
                Cập nhật giỏ hàng
              </button>
            </div>
          </motion.div>
        </div>
      </div>
    </div>
  );
}
